<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TMS AI Router</title><link rel="stylesheet" href="/assets/app.css"></head><body data-csrf="<?=htmlspecialchars($csrf)?>"><header class="topbar"><b>TMS AI Router <small>v1.0.0</small></b><form method="post" action="/logout"><button>Đăng xuất</button></form></header><main><h1>Dashboard</h1><p>AI gateway · Token & quota monitoring</p><section class="metrics"><article><span>Requests hôm nay</span><b id="mRequests"><?=number_format((int)$summary['requests'])?></b></article><article><span>Input tokens</span><b id="mInput"><?=number_format((int)$summary['input_tokens'])?></b></article><article><span>Output tokens</span><b id="mOutput"><?=number_format((int)$summary['output_tokens'])?></b></article><article><span>Total tokens</span><b id="mTotal"><?=number_format((int)$summary['total_tokens'])?></b></article></section><section class="card"><h2>Provider usage & quota</h2><div id="providerUsage"></div></section><section class="card"><div class="head"><h2>Providers</h2><button id="addProvider">+ Thêm provider</button></div><table><thead><tr><th>Tên</th><th>Base URL</th><th>Models</th><th>Priority</th><th></th></tr></thead><tbody><?php foreach($providerList as$p):?><tr><td><?=htmlspecialchars($p['name'])?></td><td><code><?=htmlspecialchars($p['base_url'])?></code></td><td><?=count($p['models'])?></td><td><?=$p['priority']?></td><td><button class="edit-provider" data-id="<?=$p['id']?>">Sửa</button> <button class="delete-provider" data-id="<?=$p['id']?>">Xóa</button></td></tr><?php endforeach;?></tbody></table></section><section class="card"><div class="head"><h2>Client API Keys</h2><button id="addKey">+ Tạo key</button></div><table><tbody><?php foreach($keyList as$k):?><tr><td><?=htmlspecialchars($k['name'])?></td><td><code><?=htmlspecialchars($k['key_prefix'])?>…</code></td><td><?=$k['enabled']?'Active':'Revoked'?></td><?php if($k['enabled']):?><td><button class="revoke-key" data-id="<?=$k['id']?>">Thu hồi</button></td><?php endif;?></tr><?php endforeach;?></tbody></table></section></main><dialog id="providerModal"><form id="providerForm"><h2>Provider</h2><input id="pId" type="hidden"><label>Tên<input id="pName" required></label><label>Base URL<input id="pBase" required placeholder="https://openrouter.ai/api/v1"></label><label>API Key<input id="pKey" type="password"></label><label>Priority<input id="pPriority" type="number" value="100"></label><label><input id="pEnabled" type="checkbox" checked> Enabled</label><label>Models<textarea id="pModels" rows="5" placeholder="gpt-4o-mini&#10;claude=anthropic/claude-sonnet"></textarea></label><label>Quota JSON<textarea id="pQuotas" rows="7">[{"label":"5 giờ","window_seconds":18000,"token_limit":0,"request_limit":0,"reset_mode":"rolling"},{"label":"Hàng ngày","window_seconds":86400,"token_limit":0,"request_limit":0,"reset_mode":"fixed"}]</textarea></label><div><button type="button" id="closeProvider">Hủy</button><button type="submit">Lưu</button></div></form></dialog><script>window.TMS_INITIAL_SUMMARY=<?=json_encode($summary,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;</script><script src="/assets/app.js"></script></body></html>